import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00
_PLAIN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _decimal_to_cents(d):
    """Exact integer cents for a finite Decimal; no context is used."""
    if not d.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = d.as_tuple()
    if sign:
        raise ValueError("amount must be positive")
    text = "".join(map(str, digits)).lstrip("0")
    if not text:
        raise ValueError("amount must be positive")
    if exp >= -2:
        if len(text) + exp > 9:  # clearly beyond the maximum
            raise ValueError("amount too large")
        cents = int(text) * 10 ** (exp + 2)
    else:
        shift = -2 - exp
        if shift > len(text) or text[len(text) - shift:].strip("0"):
            raise ValueError("amount not representable in cents")
        cents = int(text[:len(text) - shift] or "0")
    if cents <= 0:
        raise ValueError("amount must be positive")
    if cents > MAX_CENTS:
        raise ValueError("amount too large")
    return cents


def _to_cents(value):
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, Decimal):
        return _decimal_to_cents(value)
    if isinstance(value, int):
        if value > MAX_CENTS // 100:
            raise ValueError("amount too large")
        return _decimal_to_cents(Decimal(value))
    if isinstance(value, str):
        if not _PLAIN.fullmatch(value):
            raise ValueError("invalid amount string")
        return _decimal_to_cents(Decimal(value))
    raise ValueError("unsupported amount type")


def _from_cents(cents):
    return Decimal("%d.%02d" % divmod(cents, 100))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
